function getProductBrand(p) {
  if (p.brand) return String(p.brand).trim().toLowerCase();

  const name = String(p.name || "").toLowerCase();

  const brands = [
    ["apple", ["apple", "iphone", "ipad", "airpods", "آيفون", "ايفون", "آيباد"]],
    ["samsung", ["samsung", "galaxy", "سامسونج", "جالكسي"]],
    ["redmi", ["redmi", "ريدمي"]],
    ["tecno", ["tecno", "تكنو"]],
    ["xiaomi", ["xiaomi", "شاومي"]],
    ["honor", ["honor", "هونر"]],
    ["zte", ["zte", "زد تي إي"]],
    ["redmagic", ["redmagic", "red magic", "ريد ماجيك"]],
    ["huawei", ["huawei", "هواوي"]],
    ["nubia", ["nubia", "نوبيا"]]
  ];

  const match = brands.find(([brand, keywords]) =>
    keywords.some(word => name.includes(word))
  );

  return match ? match[0] : "";
}

/* ===== البحث ===== */

// توحيد الحروف العربية حتى يجد البحث "اكسسوارات" و"إكسسوارات" و"ساعه" و"ساعة"
function normalizeSearch(text) {
  return String(text || "")
    .toLowerCase()
    .replace(/[\u064B-\u065F\u0670\u0640]/g, "")
    .replace(/[أإآ]/g, "ا")
    .replace(/ى/g, "ي")
    .replace(/ة/g, "ه")
    .replace(/\s+/g, " ")
    .trim();
}

function productMatches(p, q) {
  const words = normalizeSearch(q).split(" ").filter(Boolean);
  if (!words.length) return true;

  const hay = normalizeSearch([
    p.name,
    p.brand,
    p.sub,
    CATEGORIES[p.cat] ? CATEGORIES[p.cat].title : ""
  ].join(" "));

  return words.every(w => hay.includes(w));
}

// نتائج البحث في الصفحة الرئيسية
function renderHomeSearch(scroll) {
  const input = $("searchInput");
  const q = (input ? input.value : "").trim();
  let box = $("homeSearchResults");

  if (!q) {
    if (box) box.remove();
    document.body.classList.remove("kl-searching");
    return;
  }

  const list = PRODUCTS.filter(p => productMatches(p, q));

  if (!box) {
    box = document.createElement("section");
    box.id = "homeSearchResults";
    box.className = "home-section";
    const anchor = $("promoSlider") || document.querySelector("main");
    anchor.parentNode.insertBefore(box, anchor);
  }

  box.innerHTML = `
    <div class="section-head">
      <div>
        <span class="section-kicker">نتائج البحث</span>
        <h2></h2>
        <p>${list.length ? list.length + " منتج مطابق" : "لا توجد نتائج مطابقة"}</p>
      </div>
      <button type="button" class="btn-outline" id="clearSearch">مسح البحث</button>
    </div>
    <div class="products-grid">
      ${list.length
        ? list.map(productCard).join("")
        : '<p class="empty">لم نجد منتجات بهذا الاسم. جرّب كلمة أخرى أو تصفح الأقسام.</p>'}
    </div>
  `;

  box.querySelector("h2").textContent = "«" + q + "»";

  $("clearSearch").onclick = () => {
    input.value = "";
    renderHomeSearch();
    try { history.replaceState(null, "", location.pathname); } catch (e) {}
    input.focus();
  };

  document.body.classList.add("kl-searching");

  if (scroll) {
    box.scrollIntoView({ behavior: "smooth", block: "start" });
  }
}

function applyFilters() {
  if (!grid) return;

  const q = ($("searchInput")?.value || "").trim().toLowerCase();

  let list = q
    ? (page === "home" ? PRODUCTS : baseList()).filter(p =>
        productMatches(p, q)
      )
    : baseList();

  if (page !== "home" && activeFilter !== "all") {
    list = list.filter(p => p.sub === activeFilter);
  }

  if (activeBrand !== "all") {
    list = list.filter(p =>
      getProductBrand(p) === activeBrand.toLowerCase()
    );
  }

  grid.innerHTML = list.length
    ? list.map(productCard).join("")
    : `<p class="empty">لا توجد منتجات لهذه الماركة ضمن النتائج الحالية.</p>`;
}

  
function renderCategoryPage() {
  const c = CATEGORIES[page];
  const title = $("pageTitle");
  const desc = $("pageDesc");
  const box = $("filters");

  if (!c || !title || !desc || !box || !grid) {
    console.error("تعذر تحميل القسم:", page, {
      category: c,
      pageTitle: title,
      pageDesc: desc,
      filters: box,
      productsGrid: grid
    });
    return;
  }

  title.innerHTML = catIcon(page) + " " + c.title;
  desc.textContent = c.desc;

  const all = [
    { key: "all", label: "الكل", icon: "✨" },
    ...c.filters
  ];

  box.innerHTML = all.map(f => `
    <button
      class="filter-btn ${f.key === "all" ? "active" : ""}"
      data-key="${f.key}">
      <span class="f-ico">${filterIcon(f)}</span>
      <span>${f.label}</span>
    </button>
  `).join("");

  box.addEventListener("click", e => {
    const btn = e.target.closest(".filter-btn");
    if (!btn) return;

    activeFilter = btn.dataset.key;

    box.querySelectorAll(".filter-btn").forEach(b => {
      b.classList.toggle("active", b === btn);
    });

    applyFilters();
  });
}


  function renderHomeCards() {
    $("catCards").innerHTML = Object.entries(CATEGORIES).map(([key, c]) => `
      <a href="${c.file}" class="cat-card">
        <div class="cc-text"><h3>${c.title}</h3><p>${c.desc}</p></div>
        <div class="cc-ico">${catIcon(key)}</div>
        <span class="cc-arrow">←</span>
      </a>`).join("");
  }

function renderHomeCategorySections() {
  const container = $("homeCategorySections");
  if (!container) return;

  const categoryOrder = ["smart", "accessories", "computers"];

  const html = categoryOrder.map(key => {
    const category = CATEGORIES[key];
    if (!category) return "";

    let products = PRODUCTS.filter(p => p.cat === key);

    if (activeBrand !== "all") {
      products = products.filter(p =>
        String(p.brand || "").trim().toLowerCase() ===
        String(activeBrand || "").trim().toLowerCase()
      );
    }

    products = products.slice(0, 3);

    return `
      <section class="home-section home-category-section">
        <div class="section-head">
          <div>
            <span class="section-kicker">تسوق حسب القسم</span>
            <h2>${category.icon} ${category.title}</h2>
            <p>${category.desc}</p>
          </div>

          <a class="home-more-btn" href="${category.file}">
            <span>عرض المزيد</span>
            <span class="home-more-arrow">←</span>
          </a>
        </div>

        <div class="products-grid">
          ${
            products.length
              ? products.map(productCard).join("")
              : '<p class="empty">لا توجد منتجات لهذه الماركة في هذا القسم.</p>'
          }
        </div>
      </section>
    `;
  }).join("");

  container.innerHTML = html;
}

  
