function renderSocialLinks() {
  const cfg = STORE.social || {};
  const links = Object.assign({}, cfg);

  // الواتساب يؤخذ تلقائياً من رقم المتجر إن لم يُحدد رابط
  if (!links.whatsapp && STORE.phone) {
    links.whatsapp = "https://wa.me/" + STORE.phone;
  }

  const items = Object.keys(SOCIAL_ICONS)
    .filter(key => /^https?:\/\//i.test(String(links[key] || "")))
    .map(key => {
      const icon = SOCIAL_ICONS[key];
      return `
        <li>
          <a class="kl-soc kl-soc-${key}"
             href="${links[key]}"
             target="_blank"
             rel="noopener noreferrer"
             aria-label="${icon.label}"
             title="${icon.label}">
            <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="${icon.d}"/></svg>
          </a>
        </li>`;
    });

  if (!items.length) return "";

  return `
    <div class="kl-social">
      <h3>تابعنا على مواقع التواصل</h3>
      <ul>${items.join("")}</ul>
    </div>`;
}

function setupBrandFilter() {
  const track = $("brandsTrack");
  const showAll = $("showAllBrands");

  if (track) {
  track.innerHTML = BRANDS.map(brand => `
    <button
      type="button"
      class="brand-item"
      data-brand="${brand.id}"
      aria-label="${brand.name}"
    >
      <span class="brand-logo">
  <img
    src="${brand.logo}"
    alt="${brand.name}"
    loading="lazy"
    onerror="
      this.style.display='none';
      this.parentElement.classList.add('logo-fallback');
      this.parentElement.dataset.initial='${brand.name.charAt(0)}';
    "
  >
</span>
      <span class="brand-name">${brand.name}</span>
    </button>
  `).join("");
}

  if (!track || track.dataset.ready === "1") return;
  track.dataset.ready = "1";

  function selectBrand(brand) {
    activeBrand = String(brand || "all").trim().toLowerCase();

    track.querySelectorAll(".brand-item").forEach(btn => {
      const buttonBrand = String(btn.dataset.brand || "")
        .trim()
        .toLowerCase();

      btn.classList.toggle("active", buttonBrand === activeBrand);
    });

    if (page === "home") {
      renderHomeCategorySections();
    }

    applyFilters();

    const productsGrid = $("productsGrid");

    if (productsGrid) {
      productsGrid.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    }
  }

  track.addEventListener("click", e => {
    const btn = e.target.closest(".brand-item");
    if (!btn) return;

    selectBrand(btn.dataset.brand);
  });

  showAll?.addEventListener("click", () => {
    if ($("searchInput")) {
      $("searchInput").value = "";
    }

    selectBrand("all");
  });
}


