function renderProductPage() {
 const id = params.get("id");
const p = byId(id);

console.log("صفحة المنتج:", location.href);
console.log("المعرّف في الرابط:", id);
console.log("قائمة PRODUCTS:", PRODUCTS);
console.log("عدد المنتجات:", PRODUCTS.length);
console.log("المنتج المطابق:", p);

console.log("رابط الصفحة:", location.href);
console.log("معرّف المنتج في الرابط:", id);
console.log("المنتجات المتاحة:", PRODUCTS);
console.log("المنتج المطلوب:", p);
  const box = $("productView");

  if (!box) {
    console.error("لم يتم العثور على العنصر productView");
    return;
  }

  if (!p) {
    box.innerHTML = `
      <p class="empty">
        المنتج غير موجود.
        <a href="index.html">العودة للرئيسية</a>
      </p>`;
    console.error("لم يتم العثور على المنتج ذي الرقم:", id);
    return;
  }

  const c = CATEGORIES[p.cat];

  if (!c) {
    box.innerHTML = `<p class="empty">قسم المنتج غير موجود.</p>`;
    return;
  }

  document.title = `${p.name} | ${STORE.name}`;

  const images = Array.isArray(p.images) ? p.images : [];
  const colors = Array.isArray(p.colors) ? p.colors : [];
  const specs = normalizeSpecs(p);

const firstImage = images[0] || "";

  let color = colors[0]?.name || "الافتراضي";
  let qty = 1;

  box.innerHTML = `
    <div class="crumbs">
      <a href="index.html">الرئيسية</a> ‹
      <a href="${c.file}">${c.title}</a> ‹
      <span>${p.name}</span>
    </div>

    <div class="pd">
      <div class="pd-gallery">
        <div class="pd-main">
          <img id="mainImg"
               src="${firstImage}"
               alt="${p.name}"
               onerror="imgFail(this,'${p.emoji || "📦"}')">
        </div>

        <div class="pd-thumbs">
          ${images.map((src, i) => `
            <button type="button"
                    class="thumb ${i === 0 ? "active" : ""}">
              <img src="${src}" alt="${p.name}"
                   onerror="imgFail(this,'${p.emoji || "📦"}')">
            </button>
          `).join("")}
        </div>
      </div>

      <div class="pd-info">
        <span class="pd-cat">${c.title}</span>
        <h1>${p.name}</h1>

        <div class="rating">
          <span class="stars">${stars(p.rating || 0)}</span>
          (${p.rating || 0})
        </div>

        <p class="pd-desc">${p.desc || "لا يتوفر وصف إضافي حالياً."}</p>

        <div class="pd-panel">
          <div class="pd-price">${money(Number(p.price) || 0)}</div>

          ${colors.length ? `
            <div class="pd-row">
              <b>اللون: <span id="colorName">${color}</span></b>
              <div class="swatches">
                ${colors.map((x, i) => `
                  <button type="button"
                          class="swatch ${i === 0 ? "active" : ""}"
                          data-name="${x.name}"
                          title="${x.name}"
                          aria-label="${x.name}"
                          style="--c:${x.hex || "#cccccc"}">
                  </button>
                `).join("")}
              </div>
            </div>
          ` : ""}

          <div class="pd-row">
            <b>الكمية</b>
            <div class="qty-box">
              <button type="button" id="qPlus" aria-label="زيادة الكمية">+</button>
              <span id="qVal">1</span>
              <button type="button" id="qMinus" aria-label="إنقاص الكمية">−</button>
            </div>
          </div>

          <div class="pd-total">
            الإجمالي: <b id="pdTotal">${money(Number(p.price) || 0)}</b>
          </div>

          <div class="pd-actions">
            <button type="button" class="btn-primary" id="addBtn">
              ${ic("cart")} أضف إلى السلة
            </button>
            <button type="button" class="btn-outline-big" id="buyBtn">
              ${ic("bolt")} اطلب الآن
            </button>
          </div>
        </div>

        <div class="pd-perks">
          <span>${ic("shield")} منتج أصلي</span>
          <span>${ic("truck")} توصيل لجميع المحافظات</span>
        </div>
      </div>
    </div>

    <section class="specs">
      <h3>${ic("list")} مواصفات المنتج</h3>
      <table role="table">
       ${Object.entries(specs)
  .filter(([key, value]) =>
    key && value !== null && value !== undefined && value !== ""
  )
  .map(([key, value]) => `
    <tr role="row">
      <th role="rowheader">${key}</th>
      <td role="cell">${typeof value === "object"
        ? JSON.stringify(value)
        : value}</td>
    </tr>
  `)
  .join("") || `
    <tr>
      <td colspan="2">
        لا توجد مواصفات مضافة لهذا المنتج.
      </td>
    </tr>
  `
}
      </table>
    </section>

    <div class="pd-sticky" id="pdSticky">
      <div class="pd-sticky-price">
        <small>الإجمالي</small>
        <b id="pdTotal2">${money(Number(p.price) || 0)}</b>
      </div>
      <button type="button" class="btn-primary" id="addBtn2">
        ${ic("cart")} أضف إلى السلة
      </button>
    </div>
  `;

  box.querySelectorAll(".thumb").forEach(btn => {
    btn.addEventListener("click", () => {
      const img = btn.querySelector("img");
      $("mainImg").src = img.src;

      box.querySelectorAll(".thumb").forEach(item => {
        item.classList.toggle("active", item === btn);
      });
    });
  });

  box.querySelectorAll(".swatch").forEach(btn => {
    btn.addEventListener("click", () => {
      color = btn.dataset.name;
      $("colorName").textContent = color;

      box.querySelectorAll(".swatch").forEach(item => {
        item.classList.toggle("active", item === btn);
      });
    });
  });

  const setQty = n => {
    qty = Math.min(20, Math.max(1, n));
    $("qVal").textContent = qty;
    $("pdTotal").textContent = money((Number(p.price) || 0) * qty);
    const t2 = $("pdTotal2");
    if (t2) t2.textContent = $("pdTotal").textContent;
  };

  $("qPlus").onclick = () => setQty(qty + 1);
  $("qMinus").onclick = () => setQty(qty - 1);

  $("addBtn").onclick = () => {
    addToCart(p.id, color, qty);
    openCart();
  };

  $("buyBtn").onclick = () => {
    addToCart(p.id, color, qty);
    openCheckout();
  };

  const stickyAdd = $("addBtn2");
  if (stickyAdd) {
    stickyAdd.onclick = () => {
      addToCart(p.id, color, qty);
      openCart();
    };
  }

  // يظهر شريط الشراء السفلي عندما تغيب أزرار الشراء عن الشاشة
  const sticky = $("pdSticky");
  const actionsBox = box.querySelector(".pd-actions");
  if (sticky && actionsBox && "IntersectionObserver" in window) {
    new IntersectionObserver(([entry]) => {
      sticky.classList.toggle("show", !entry.isIntersecting && entry.boundingClientRect.top < 0);
    }).observe(actionsBox);
  }

  const relatedGrid = $("relatedGrid");

  if (relatedGrid) {
    const related = PRODUCTS
      .filter(item =>
        item.cat === p.cat &&
        String(item.id) !== String(p.id)
      )
      .slice(0, 4);

    relatedGrid.innerHTML = related.length
      ? related.map(productCard).join("")
      : `<p class="empty">لا توجد منتجات مشابهة حالياً.</p>`;
  }
}

  
