  // ================= كلمات ريلز =================

  
let reelsLoadedFromSupabase = false;

function getReels() {
  // إذا تم تحميل البيانات من Supabase، اعتمد عليها مباشرة
  // حتى لو كانت القائمة فارغة، ولا تعرض الريلز القديمة.
  if (reelsLoadedFromSupabase) {
    return Array.isArray(window.STORE_REELS)
      ? window.STORE_REELS.filter(reel => reel && reel.url)
      : [];
  }

  // بديل مؤقت فقط إذا لم يتم تحميل بيانات Supabase
  try {
    const data = JSON.parse(
      localStorage.getItem("klmat_reels_v1") || "[]"
    );

    return Array.isArray(data)
      ? data.filter(reel => reel && reel.url)
      : [];
  } catch (error) {
    console.error("تعذر قراءة الريلز:", error);
    return [];
  }
}

  function escapeReelText(value) {
    return String(value ?? "").replace(/[&<>"']/g, char => ({
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;",
      "'": "&#39;"
    })[char]);
  }

  function renderReelsHome() {
    const section = $("homeReelsSection");
    const track = $("homeReelsTrack");

    if (!section || !track) {
      console.warn("قسم الريلز غير موجود في index.html");
      return;
    }

    section.hidden = false;
    section.style.display = "block";

    const reels = getReels();

    if (!reels.length) {
      track.innerHTML = `
        <div class="reels-empty">
          <div style="font-size:36px">🎬</div>
          <h3>كلمات ريلز</h3>
          <p>ستظهر مقاطع المنتجات هنا قريباً.</p>
        </div>
      `;
      return;
    }

    track.innerHTML = reels.slice(0, 8).map((reel, index) => `
      <a class="reel-tile" href="reels.html?reel=${index}">
        <video
          src="${escapeReelText(reel.url)}"
          muted
          playsinline
          preload="metadata">
        </video>
        <span>${escapeReelText(reel.title || "شاهد المقطع")}</span>
        <b class="reel-play-icon">▶</b>
      </a>
    `).join("");
  }

  

function renderReelPage() {
  const viewer = $("reelsViewer");
  if (!viewer) return;

  const reels = getReels();

  if (!reels.length) {
    viewer.innerHTML = `
      <div class="reels-empty">
        <h3>🎬 لا توجد مقاطع حالياً</h3>
        <p>ستظهر هنا مقاطع المنتجات عند نشرها.</p>
      </div>`;
    return;
  }

  const requested = parseInt(params.get("reel") || "0", 10);
  let current =
    Number.isInteger(requested) &&
    requested >= 0 &&
    requested < reels.length
      ? requested
      : 0;

  let reelMuted = false;

  function show(index) {
    current = (index + reels.length) % reels.length;
    const reel = reels[current];

    viewer.innerHTML = `
      <video
        id="activeReelVideo"
        src="${escapeReelText(reel.url)}"
        autoplay
        playsinline
        preload="metadata">
      </video>

      <button type="button" class="reel-tap" id="reelTap"
              aria-label="تشغيل أو إيقاف المقطع"></button>

      <div class="reel-flash" id="reelFlash" aria-hidden="true">${ic("play")}</div>

      <div class="reel-top">
        <span class="reel-counter">${current + 1} / ${reels.length}</span>
        <button type="button" class="reel-mute" id="reelMute"
                aria-label="كتم الصوت أو تشغيله">${ic(reelMuted ? "volume-off" : "volume")}</button>
      </div>

      <div class="reel-caption">
        <h3>${escapeReelText(reel.title || "منتج من متجرنا")}</h3>
        ${
          reel.productId
            ? `<a class="reels-product-link"
                 href="product.html?id=${encodeURIComponent(reel.productId)}">
                 ${ic("bag")} عرض المنتج
               </a>`
            : ""
        }
      </div>

      <div class="reel-progress"><i id="reelBar"></i></div>`;

    const video = $("activeReelVideo");

    if (video) {
      video.muted = reelMuted;

      const flash = $("reelFlash");
      const syncFlash = () => viewer.classList.toggle("is-paused", video.paused);

      video.addEventListener("loadedmetadata", () => {
        viewer.classList.toggle("is-landscape", video.videoWidth > video.videoHeight);
      });

      video.addEventListener("play", syncFlash);
      video.addEventListener("pause", syncFlash);

      video.addEventListener("timeupdate", () => {
        const bar = $("reelBar");
        if (bar && video.duration) {
          bar.style.width = (video.currentTime / video.duration * 100) + "%";
        }
      });

      // عند انتهاء المقطع ننتقل للتالي (أو نعيد المقطع الوحيد)
      video.addEventListener("ended", () => {
        if (reels.length > 1) show(current + 1);
        else { video.currentTime = 0; video.play().catch(() => {}); }
      });

      $("reelTap").onclick = () => {
        if (video.paused) video.play().catch(() => {});
        else video.pause();
      };

      $("reelMute").onclick = () => {
        reelMuted = !reelMuted;
        video.muted = reelMuted;
        $("reelMute").innerHTML = ic(reelMuted ? "volume-off" : "volume");
      };

      video.load();
      video.play().catch(() => syncFlash());
    }

    // تحديث رقم الريل في الرابط
    const url = new URL(location.href);
    url.searchParams.set("reel", current);
    history.replaceState(null, "", url);
  }

  // منع تكرار مستمعات الأزرار عند إعادة العرض
  const prev = $("reelPrev");
  const next = $("reelNext");

  if (prev) {
    prev.onclick = () => show(current - 1);
  }

  if (next) {
    next.onclick = () => show(current + 1);
  }

  // السحب العمودي للتنقل بين الريلز
  let startY = 0;
  let startX = 0;

  viewer.ontouchstart = event => {
    const touch = event.changedTouches[0];
    startY = touch.clientY;
    startX = touch.clientX;
  };

  viewer.ontouchend = event => {
    const touch = event.changedTouches[0];
    const deltaY = touch.clientY - startY;
    const deltaX = touch.clientX - startX;

    // تجاهل السحب الأفقي أو الحركة القصيرة
    if (
      Math.abs(deltaY) < 55 ||
      Math.abs(deltaY) < Math.abs(deltaX) * 1.2
    ) {
      return;
    }

    if (deltaY < 0) {
      show(current + 1); // سحب للأعلى: التالي
    } else {
      show(current - 1); // سحب للأسفل: السابق
    }
  };

  if (!window.__reelKeys) {
    window.__reelKeys = true;
    document.addEventListener("keydown", e => {
      if (e.key === "ArrowDown") { e.preventDefault(); $("reelNext")?.click(); }
      if (e.key === "ArrowUp") { e.preventDefault(); $("reelPrev")?.click(); }
    });
  }

  show(current);
}



  
